export const approvedCampaignCards: ManagedCard[] = campaignAbilityPack
  .filter((seed) => approvedCampaignCardIds.has(seed.card.id))
  .map((seed) => ({
    ...seed.card,
    tags: [...seed.card.tags],
    assignedTo: [],
    customFields: { ...seed.card.customFields },
  }));

export function getCampaignAbilityPackSummary() {
  return campaignAbilityPack.reduce(
    (summary, seed) => {
      summary.total += 1;
      summary.byOwner[seed.ownerName] += 1;
      if (seed.magicStage) summary.spells += 1;
      if ((seed.balance?.rating ?? 0) >= 2) summary.majorBalanceFlags += 1;
      return summary;
    },
    {
      total: 0,
      spells: 0,
      majorBalanceFlags: 0,
      byOwner: { Lotus: 0, Alice: 0, Unassigned: 0 },
    },
  );
}
